    ('2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Quiz — Une région à plusieurs vitesses', 'Histoire-Géographie', '2de', 'Les défis de la transition et du développement pour les pays d’Afrique australe inégalement développés', '1a585eef-9953-54dd-bec4-436b729e114f'::uuid),
    ('f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Quiz — Migrations de travail, villes qui gonflent, touristes qui passent', 'Histoire-Géographie', '2de', 'Des territoires d’Afrique australe transformés par les mobilités', '26d7bcb5-9060-5006-8594-413182438756'::uuid)
