ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('7fe88758-fb51-5671-8b9d-96a8ece4dd5b'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'Quel événement marque traditionnellement le passage de la Préhistoire à l’Antiquité ?', 'mcq', '["L’invention de l’écriture","La découverte du feu","La naissance de l’agriculture","La fondation de Rome"]'::jsonb, 0, 'Vers 3300 av. J.-C. en Mésopotamie : le passé devient lisible autrement que par les objets.', 1),
    ('33b64d14-a83d-5744-b7cd-36b7bd8ec3b5'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'Quelle date clôt habituellement le Moyen Âge en France ?', 'mcq', '["1492","476","1789","1918"]'::jsonb, 0, 'L’arrivée de Colomb en Amérique ; certains manuels retiennent 1453, la prise de Constantinople.', 2),
    ('25b97068-910e-5415-b0df-a8d978559c2d'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'L’époque contemporaine commence en 1789.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La Révolution française sert de borne — un choix européen, et assumé comme tel.', 3),
    ('bfece944-e432-5152-a2c4-4e9338bc6069'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'À quelles années correspond le XVIIIe siècle ?', 'mcq', '["1701-1800","1700-1799","1800-1899","1750-1850"]'::jsonb, 0, 'Un siècle commence à l’année 1 : il n’y a pas d’année zéro.', 4),
    ('05ff6f0c-a6e9-5293-b2b2-25e759d0a11e'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'Le découpage en cinq périodes vaut-il pour toutes les régions du monde ?', 'mcq', '["Non, il est né en Europe et éclaire surtout son histoire","Oui, il est universel","Oui, il est fixé par l’ONU","Non, il ne vaut que pour la France"]'::jsonb, 0, 'Appliqué à la Chine ou à l’Afrique, il masque plus qu’il ne montre.', 5),
    ('d18dcc51-500f-54c2-b9dc-dd17bf9b868b'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'Qu’appelle-t-on une source en histoire ?', 'mcq', '["Une trace du passé sur laquelle l’historien travaille","Un manuel scolaire","Une hypothèse d’historien","Un musée"]'::jsonb, 0, 'Écrite, matérielle, orale ou iconographique — encore faut-il la critiquer.', 6),
    ('e3a0d4d5-05ad-574e-9768-8f84e79601a8'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'Que signifie critiquer une source ?', 'mcq', '["Se demander qui parle, quand, pour qui et pourquoi","La rejeter comme fausse","La résumer","La traduire"]'::jsonb, 0, 'La critique ne détruit pas la source : elle en fixe la portée.', 7),
    ('d5dee5ca-3201-50f8-8aae-56781a0645d7'::uuid, '8ac5a43b-173c-517c-b30f-d511118c353a'::uuid, 'La chute de l’Empire romain d’Occident date de 476.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Déposition de Romulus Augustule — une borne commode, longtemps préparée.', 8),
    ('60e0f30a-202d-59c8-82da-317a9ad93759'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Qu’est-ce qu’une cité grecque ?', 'mcq', '["Un État indépendant fait d’une ville et de son territoire","Une capitale de royaume","Un simple port de commerce","Une colonie romaine"]'::jsonb, 0, 'Athènes, Sparte, Corinthe : des centaines de cités, chacune avec ses lois.', 1),
    ('4f915964-c8f7-5346-a7bf-44d0337ec822'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Quelle réforme de Solon sauve la petite paysannerie ?', 'mcq', '["L’abolition de l’esclavage pour dettes","Le partage général des terres","La création de la Boulè","L’ostracisme"]'::jsonb, 0, 'En 594, l’endettement ne peut plus réduire un Athénien en esclavage.', 2),
    ('53b758e2-8e04-54fe-bb6a-b049e8e9eea0'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Que fait Clisthène en 508-507 av. J.-C. ?', 'mcq', '["Il redécoupe la cité en dèmes et dix tribus mêlant les régions","Il écrit les premières lois","Il instaure la tyrannie","Il crée la ligue de Délos"]'::jsonb, 0, 'Le brassage géographique brise les clientèles aristocratiques.', 3),
    ('a948d5d8-a5d2-5aec-a06c-e88f6bd6713c'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Qu’est-ce que l’ostracisme ?', 'mcq', '["L’exil de dix ans d’un citoyen jugé dangereux pour la cité","Une amende infligée aux riches","Une taxe sur le commerce","Une charge religieuse"]'::jsonb, 0, 'Le nom est gravé sur un tesson, l’ostrakon, d’où le mot.', 4),
    ('2c20c231-138b-5c21-af4c-fc761362701d'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Les femmes athéniennes étaient citoyennes de plein droit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles transmettent la citoyenneté mais ne votent ni ne siègent.', 5),
    ('a75e459d-e82c-5e04-8b28-cc58e7b0146a'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Qui sont les métèques ?', 'mcq', '["Des étrangers libres installés à Athènes, non citoyens","Des esclaves affranchis","Des citoyens pauvres","Des soldats étrangers"]'::jsonb, 0, 'Ils paient un impôt spécifique et participent à l’économie sans voter.', 6),
    ('470b03e2-c0d9-5636-a8e2-c9e225811a05'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Quel tyran affaiblit l’aristocratie foncière au VIe siècle av. J.-C. ?', 'mcq', '["Pisistrate","Dracon","Périclès","Thémistocle"]'::jsonb, 0, 'Sa tyrannie (561-527) prépare paradoxalement la démocratie.', 7),
    ('f5747632-7602-5b51-95fb-e39657f16e7f'::uuid, '9de2ea10-d07b-5d38-a0ac-18a35805389a'::uuid, 'Que change Dracon en 621 av. J.-C. ?', 'mcq', '["Il fait mettre les lois par écrit","Il abolit la dette","Il crée le tirage au sort","Il fonde la marine"]'::jsonb, 0, 'Une loi écrite est une loi opposable : elle échappe au monopole des nobles.', 8),
    ('970bd185-e068-5509-a341-c17e81424119'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'Quelle bataille navale de 480 av. J.-C. sauve la Grèce des Perses ?', 'mcq', '["Salamine","Marathon","Platées","Actium"]'::jsonb, 0, 'Elle donne un rôle décisif aux rameurs, les citoyens les plus pauvres.', 1),
    ('6239a965-4e00-5d9a-8a63-5fcc7a3741ad'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'Où se réunit l’Ecclésia ?', 'mcq', '["Sur la colline de la Pnyx","Sur l’Acropole","Dans le Parthénon","Au port du Pirée"]'::jsonb, 0, 'Une quarantaine de réunions par an, ouvertes à tous les citoyens.', 2),
    ('18bdebb0-2132-5950-8457-3b6edec7a37f'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'Comment sont désignés les 500 membres de la Boulè ?', 'mcq', '["Par tirage au sort","Par élection censitaire","Par hérédité","Par les stratèges"]'::jsonb, 0, 'Le tirage au sort suppose que tout citoyen peut gouverner.', 3),
    ('9575d76d-c86c-53e6-b116-4bfd63ce95b9'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'Quelle magistrature est élue et non tirée au sort ?', 'mcq', '["Les stratèges","Les héliastes","Les bouleutes","Les archontes"]'::jsonb, 0, 'Commander une armée exige une compétence : Périclès est stratège quinze fois.', 4),
    ('4e788f9c-1a91-5f86-acc3-ca6b92762f4a'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'Qu’est-ce que le misthos ?', 'mcq', '["Une indemnité versée aux citoyens exerçant une charge","Un impôt sur les métèques","Le tribut des alliés","Une amende judiciaire"]'::jsonb, 0, 'Sans elle, seuls les riches auraient eu le temps de gouverner.', 5),
    ('9bbd916a-ebab-537c-b759-8a01c4d58257'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'En quoi la ligue de Délos se transforme-t-elle ?', 'mcq', '["En empire maritime au profit d’Athènes","En alliance avec Sparte","En confédération égalitaire","En ligue commerciale perse"]'::jsonb, 0, 'Trésor transféré en 454, tribut détourné vers les grands travaux.', 6),
    ('5d2a9e9b-0f61-5bc9-8d05-a634224706a1'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'Le tribut versé par les alliés s’appelle le phoros.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il finance notamment la reconstruction de l’Acropole.', 7),
    ('5b80888c-eb22-5bb0-b411-29995d6ad38a'::uuid, '79ac5d67-bd03-5e1c-9346-f9cbaafde716'::uuid, 'Quel conflit oppose Athènes à Sparte de 431 à 404 av. J.-C. ?', 'mcq', '["La guerre du Péloponnèse","Les guerres médiques","La guerre de Troie","La guerre sociale"]'::jsonb, 0, 'La défaite met fin à l’hégémonie athénienne.', 8),
    ('5684fa79-1c5d-58ee-8796-1fc945ebcfda'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'En quelle année Octave devient-il Auguste ?', 'mcq', '["27 av. J.-C.","44 av. J.-C.","212 apr. J.-C.","476 apr. J.-C."]'::jsonb, 0, 'Le Principat conserve les apparences de la République.', 1),
    ('188b1d89-e987-5af2-9c2f-45ce10318957'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'Comment les Romains appelaient-ils la Méditerranée ?', 'mcq', '["Mare Nostrum","Pax Romana","Limes","Imperium"]'::jsonb, 0, 'Notre mer : la Méditerranée est devenue un lac romain.', 2),
    ('7a5958af-253c-53bc-becc-342613c06f09'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'Sous quel empereur l’Empire atteint-il son extension maximale ?', 'mcq', '["Trajan","Auguste","Constantin","Néron"]'::jsonb, 0, 'Entre 98 et 117, de la Bretagne à la Mésopotamie.', 3),
    ('d3524bcd-3677-5802-922a-5dcd9ddecbfe'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'Qu’accorde l’édit de Caracalla en 212 ?', 'mcq', '["La citoyenneté romaine à presque tous les hommes libres de l’Empire","La liberté de culte aux chrétiens","L’affranchissement des esclaves","L’exemption d’impôt aux provinces"]'::jsonb, 0, 'L’aboutissement d’une longue extension de la citoyenneté.', 4),
    ('0c9f0028-9166-54b0-af14-4d79ef75bcd1'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'Qu’appelle-t-on le limes ?', 'mcq', '["La frontière fortifiée de l’Empire","Le forum d’une ville romaine","Le tribut des provinces","Le conseil de l’empereur"]'::jsonb, 0, 'Mur d’Hadrien, fortins du Rhin et du Danube.', 5),
    ('ea0d7cb8-4f94-58e1-bf01-3b16c9cfe3c0'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'La romanisation passe surtout par les campagnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle passe d’abord par les villes et par les élites locales.', 6),
    ('cf7fd51d-d833-530f-9b8d-799003e7450e'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'Contre quelle cité Rome mène-t-elle les guerres puniques ?', 'mcq', '["Carthage","Athènes","Alexandrie","Syracuse"]'::jsonb, 0, 'Trois guerres, de 264 à 146 av. J.-C., et la destruction de Carthage.', 7),
    ('f1cfed6b-377f-56e0-aaca-34c87f7225d1'::uuid, 'c3cd8b51-c80c-5fbf-9c63-96993bedfacd'::uuid, 'Qu’est-ce que la paix romaine ?', 'mcq', '["Une longue période de paix et de prospérité dans les provinces","Un traité avec les Perses","La fin de l’esclavage","Un culte impérial"]'::jsonb, 0, 'Elle dure du règne d’Auguste au IIe siècle.', 8),
    ('3acd2805-6fd7-59f9-a797-2a4e1ec423c4'::uuid, 'f53f2411-1e5f-5bba-8453-983a1365ce0b'::uuid, 'Qu’accorde l’édit de Milan en 313 ?', 'mcq', '["La liberté de culte, notamment aux chrétiens","Le statut de religion officielle au christianisme","La citoyenneté à tous les habitants","L’exil des païens"]'::jsonb, 0, 'Tolérance d’abord ; l’officialisation viendra avec Théodose.', 1),
    ('390d6627-4de6-598d-becf-1feeeb09dc22'::uuid, 'f53f2411-1e5f-5bba-8453-983a1365ce0b'::uuid, 'Qui fait du christianisme la religion officielle de l’Empire ?', 'mcq', '["Théodose, vers 380-392","Constantin en 313","Dioclétien en 303","Justinien en 529"]'::jsonb, 0, 'L’édit de Thessalonique, puis l’interdiction des cultes païens.', 2),
    ('8947dfcc-0864-50af-bfc6-f6795eb29d0f'::uuid, 'f53f2411-1e5f-5bba-8453-983a1365ce0b'::uuid, 'Quelle bataille donne le pouvoir à Constantin en 312 ?', 'mcq', '["Le pont Milvius","Andrinople","Actium","Zama"]'::jsonb, 0, 'La tradition chrétienne y place le signe du Chrisme.', 3),
    ('36dac511-c54c-541c-9468-3edbdede36ab'::uuid, 'f53f2411-1e5f-5bba-8453-983a1365ce0b'::uuid, 'Que décide le concile de Nicée en 325 ?', 'mcq', '["Il tranche la querelle sur la nature du Christ","Il fonde Constantinople","Il divise l’Empire en deux","Il abolit l’esclavage"]'::jsonb, 0, 'L’arianisme est condamné : l’empereur arbitre le dogme.', 4),
    ('69c0c50e-e9df-54a8-a7ec-a6bde8283e8a'::uuid, 'f53f2411-1e5f-5bba-8453-983a1365ce0b'::uuid, 'En quelle année Constantinople est-elle fondée ?', 'mcq', '["330","313","395","476"]'::jsonb, 0, 'Sur le site de l’ancienne Byzance, entre Europe et Asie.', 5),
    ('ea89894a-2ee9-5e18-af6b-a4e274011da4'::uuid, 'f53f2411-1e5f-5bba-8453-983a1365ce0b'::uuid, 'Le partage définitif de l’Empire entre Orient et Occident date de 395.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À la mort de Théodose, entre ses deux fils.', 6),
