    ('bb1224dc-5cda-56f9-94e4-13f92cabfd44'::uuid, 'b7e4db74-df37-5e92-9ea3-b7f28af60e1e'::uuid, 'Pourquoi Henri VIII rompt-il avec Rome en 1534 ?', 'mcq', '["Pour obtenir son divorce et prendre la tête de l’Église d’Angleterre","Par adhésion au luthéranisme","Pour supprimer la messe","Sous la pression du Parlement écossais"]'::jsonb, 0, 'L’Acte de suprématie fait du roi le chef de l’Église anglicane.', 3),
    ('bd1dd80c-cc81-50ea-8917-e4779dc5b977'::uuid, 'b7e4db74-df37-5e92-9ea3-b7f28af60e1e'::uuid, 'Que fait le concile de Trente entre 1545 et 1563 ?', 'mcq', '["Il réaffirme les dogmes catholiques et corrige les abus","Il réconcilie catholiques et protestants","Il abolit le culte des saints","Il crée l’Église anglicane"]'::jsonb, 0, 'Séminaires, catéchisme, discipline du clergé : la Réforme catholique.', 4),
    ('ed06947d-b60e-5c87-b3cd-e37528e7cf3a'::uuid, 'b7e4db74-df37-5e92-9ea3-b7f28af60e1e'::uuid, 'Quel ordre religieux, fondé en 1540, se consacre à l’enseignement et à la mission ?', 'mcq', '["Les jésuites","Les bénédictins","Les franciscains","Les dominicains"]'::jsonb, 0, 'Fondé par Ignace de Loyola, il devient le bras éducatif de Rome.', 5),
    ('d355d957-46f9-525f-b306-606ea6da7ca4'::uuid, 'b7e4db74-df37-5e92-9ea3-b7f28af60e1e'::uuid, 'La paix d’Augsbourg de 1555 laisse chaque prince choisir la religion de ses sujets.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La formule consacre la division religieuse de l’Empire.', 6),
    ('bbe684f0-bc3d-535c-977c-381a3a0dbbdb'::uuid, 'b7e4db74-df37-5e92-9ea3-b7f28af60e1e'::uuid, 'Quel massacre marque les guerres de Religion françaises en 1572 ?', 'mcq', '["La Saint-Barthélemy","La journée des Barricades","Le sac de Rome","La défenestration de Prague"]'::jsonb, 0, 'Des milliers de protestants tués à Paris et en province.', 7),
    ('63e86fc0-0d10-5de6-9cbf-3366c6fb4592'::uuid, 'b7e4db74-df37-5e92-9ea3-b7f28af60e1e'::uuid, 'Qu’accorde l’édit de Nantes en 1598 ?', 'mcq', '["La liberté de conscience et des places de sûreté aux protestants","L’égalité totale des cultes","La suppression du catholicisme d’État","L’expulsion des jésuites"]'::jsonb, 0, 'Signé par Henri IV, il sera révoqué en 1685.', 8),
    ('17117349-b4d0-5b73-81e9-9a8741a51bb8'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'En quelle année Luther rédige-t-il ses 95 thèses ?', 'mcq', '["1517","1521","1534","1555"]'::jsonb, 0, 'Contre les indulgences, à Wittenberg.', 1),
    ('7d315dd8-c563-5882-b590-6e9e80c321df'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'Quel principe résume la doctrine luthérienne du salut ?', 'mcq', '["Le salut par la foi seule","Le salut par les œuvres","Le salut par les indulgences","Le salut par les sacrements"]'::jsonb, 0, 'Avec l’Écriture seule et le sacerdoce universel.', 2),
    ('3ee3dbae-93ce-5658-8cc1-15a8ec232653'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'Devant qui Luther refuse-t-il de se rétracter en 1521 ?', 'mcq', '["Charles Quint, à la diète de Worms","Le pape Léon X, à Rome","François Ier, à Paris","Le concile de Trente"]'::jsonb, 0, 'Il est ensuite mis au ban de l’Empire.', 3),
    ('1df9e634-d070-50a4-ac73-0e830730918f'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'Que traduit Luther pendant sa retraite à la Wartburg ?', 'mcq', '["Le Nouveau Testament en allemand","Le Coran en latin","La Somme théologique","Les Évangiles en français"]'::jsonb, 0, 'Une traduction qui fixe durablement la langue allemande écrite.', 4),
    ('713c68e8-c853-5327-84cb-a3f359463b74'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'Combien de sacrements le luthéranisme conserve-t-il ?', 'mcq', '["Deux","Sept","Trois","Aucun"]'::jsonb, 0, 'Le baptême et l’eucharistie, les seuls fondés sur l’Écriture selon Luther.', 5),
    ('7ca2293f-2098-566f-bcc7-b719f11ab7c8'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'Luther soutient la révolte des paysans de 1524-1525.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il appelle au contraire les princes à l’écraser.', 6),
    ('f7c43d7d-a6f8-5607-ab84-449eaba428e7'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'Pourquoi certains princes allemands adoptent-ils la Réforme ?', 'mcq', '["Par conviction, mais aussi pour saisir les biens de l’Église","Pour obéir au pape","Pour rejoindre l’Empire ottoman","Pour éviter la guerre avec la France"]'::jsonb, 0, 'La sécularisation des biens ecclésiastiques est un gain considérable.', 7),
    ('67cfc28e-8f38-5af1-b97d-06e2a197635a'::uuid, '89cf4544-b565-527e-877a-7b569e78fb33'::uuid, 'Quelle est la conséquence religieuse durable de la paix d’Augsbourg ?', 'mcq', '["Le nord de l’Allemagne devient luthérien, le sud reste catholique","L’Allemagne devient entièrement protestante","Le calvinisme devient religion d’Empire","Le pape reprend le contrôle de l’Empire"]'::jsonb, 0, 'Une frontière confessionnelle encore lisible aujourd’hui.', 8),
    ('13ed307e-1ca1-589b-aa55-cf9d845e10d9'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Dans l’atelier de quel maître florentin Léonard se forme-t-il ?', 'mcq', '["Verrocchio","Botticelli","Michel-Ange","Raphaël"]'::jsonb, 0, 'On y apprenait autant la mécanique que la peinture.', 1),
    ('bbf4d6ad-c917-5af5-b9a0-827f6e7c6653'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Quelle technique picturale Léonard perfectionne-t-il ?', 'mcq', '["Le sfumato","Le pointillisme","La fresque sèche","Le clair-obscur ténébriste"]'::jsonb, 0, 'Un fondu qui adoucit les contours et les passages de lumière.', 2),
    ('b2f2ef76-edc8-5436-a61d-d040220c5003'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Où se trouve la Cène peinte par Léonard ?', 'mcq', '["À Milan","À Florence","À Rome","À Amboise"]'::jsonb, 0, 'Dans le réfectoire de Santa Maria delle Grazie.', 3),
    ('1b7aeaaf-0076-5f9c-b08b-4affd67c7fe9'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Que contiennent les carnets de Léonard ?', 'mcq', '["Des dessins scientifiques, techniques et anatomiques","Uniquement des esquisses de tableaux","Sa correspondance diplomatique","Des poèmes en latin"]'::jsonb, 0, 'Écrits en miroir, ils mêlent art et science sans les séparer.', 4),
    ('9778c678-5350-5307-8efe-140b671cff8f'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Quel roi de France invite Léonard en 1516 ?', 'mcq', '["François Ier","Louis XII","Henri II","Charles VIII"]'::jsonb, 0, 'Il l’installe au Clos Lucé, près du château d’Amboise.', 5),
    ('a47c5473-341f-58d5-a5df-cf7aebcf14ea'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Léonard a réalisé la plupart des machines qu’il a dessinées.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des projets, rarement construits de son vivant.', 6),
    ('89717bf0-c986-59f2-be96-1bd77853e75c'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Pourquoi Léonard incarne-t-il l’idéal humaniste ?', 'mcq', '["Il unit l’art, la technique et la science dans une même curiosité","Il a traduit la Bible","Il a fondé une université","Il a dirigé un État"]'::jsonb, 0, 'L’homme universel, capable dans tous les domaines.', 7),
    ('ec5ea219-b4c2-50fd-9d9a-2675dd99e97e'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'En quelle année Léonard meurt-il ?', 'mcq', '["1519","1492","1547","1503"]'::jsonb, 0, 'À Amboise, au service du roi de France.', 8),
    ('5cb9e9d9-1d47-5e87-8373-e590b18cfc69'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'D’où le roi absolu tient-il son pouvoir selon la doctrine du temps ?', 'mcq', '["De Dieu","Du peuple","Des états généraux","Du Parlement de Paris"]'::jsonb, 0, 'C’est la monarchie de droit divin.', 1),
    ('942f20c5-aab3-559d-b3be-4e6d61386d4d'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Le pouvoir absolu signifie-t-il un pouvoir sans aucune limite ?', 'mcq', '["Non : lois fondamentales, coutumes et privilèges le bornent","Oui, le roi peut tout","Oui, sauf en matière religieuse","Non, il est limité par une constitution écrite"]'::jsonb, 0, 'Absolu ne veut pas dire arbitraire.', 2),
    ('f1d560d6-8076-55a3-b5c5-2ef83d9308c0'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Quel ministre de Louis XIII crée les intendants ?', 'mcq', '["Richelieu","Sully","Colbert","Mazarin"]'::jsonb, 0, 'Des agents révocables envoyés dans les provinces au nom du roi.', 3),
    ('ca28b29e-ec5a-597e-83be-ee6bc2e2626a'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Qu’est-ce que la Fronde ?', 'mcq', '["Une révolte des parlements et des princes entre 1648 et 1653","Une guerre contre l’Espagne","Une révolte paysanne bretonne","Un complot protestant"]'::jsonb, 0, 'Elle marque durablement le jeune Louis XIV.', 4),
    ('dacc8d88-5efe-5cc4-94cb-ca0ea8fd7cf2'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'En quelle année Louis XIV commence-t-il son règne personnel ?', 'mcq', '["1661","1643","1682","1685"]'::jsonb, 0, 'À la mort de Mazarin, il décide de gouverner sans principal ministre.', 5),
    ('1220f6c1-8e84-5005-8561-f60fc01d47cf'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Louis XIV réunit régulièrement les états généraux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils ne sont plus convoqués de 1614 à 1789.', 6),
    ('dfb9176f-155d-5288-8992-eb530a2cf0f5'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'En quelle année la cour s’installe-t-elle à Versailles ?', 'mcq', '["1682","1661","1715","1670"]'::jsonb, 0, 'La noblesse y vit sous le regard permanent du roi.', 7),
    ('a6b7ec9c-80a4-5d21-9dd2-96d8f323f805'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'À quoi sert l’étiquette de la cour ?', 'mcq', '["À hiérarchiser la noblesse et à la tenir sous le contrôle du roi","À réduire les dépenses de la cour","À former les officiers","À organiser la justice"]'::jsonb, 0, 'Un lever du roi est un acte politique.', 8),
    ('cab85316-e08d-5a9d-832d-501758e79f9b'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quel principe fonde le mercantilisme ?', 'mcq', '["Vendre à l’étranger plus qu’on ne lui achète pour attirer les métaux précieux","Supprimer les droits de douane","Laisser faire le marché","Interdire le commerce extérieur"]'::jsonb, 0, 'La richesse mondiale y est vue comme une somme fixe.', 1),
    ('15c40f5c-6ac1-5ff6-b70b-dbddf6c93a5d'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quelle fonction Colbert occupe-t-il auprès de Louis XIV ?', 'mcq', '["Contrôleur général des finances","Chancelier de France","Connétable","Archevêque de Paris"]'::jsonb, 0, 'De 1665 à 1683, il tient aussi la marine et les manufactures.', 2),
    ('b5129c3a-e301-5729-9e17-3e20ade0ed93'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Qu’est-ce qu’une manufacture royale ?', 'mcq', '["Un établissement de production privilégié et contrôlé par l’État","Un marché hebdomadaire","Un entrepôt portuaire","Une corporation d’artisans"]'::jsonb, 0, 'Gobelins, Saint-Gobain : qualité imposée, débouchés garantis.', 3),
    ('0cf1e4e5-ed70-51ab-88c4-6502a042c5b6'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quel grand ouvrage reliant l’Atlantique à la Méditerranée est achevé en 1681 ?', 'mcq', '["Le canal du Midi","Le canal de Bourgogne","Le canal Saint-Martin","Le canal de Briare"]'::jsonb, 0, 'Conçu par Pierre-Paul Riquet.', 4),
    ('ed270911-879c-5491-afab-b4f37e48231c'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quelle mesure de 1685 prive le royaume de nombreux artisans et négociants ?', 'mcq', '["La révocation de l’édit de Nantes","La création de la taille","La fermeture des ports","L’édit de Villers-Cotterêts"]'::jsonb, 0, 'Les protestants émigrent vers l’Angleterre, la Hollande et la Prusse.', 5),
    ('52f511a8-0cb4-50e1-bd35-c49cdd67b9a8'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'La taille était payée par la noblesse et le clergé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils en sont exemptés : le poids retombe sur les paysans.', 6),
    ('4ed67328-0c8d-56a6-9c9d-04c460106bbf'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Pourquoi Colbert relève-t-il les tarifs douaniers en 1664 et 1667 ?', 'mcq', '["Pour protéger la production française de la concurrence étrangère","Pour financer Versailles","Pour plaire aux marchands hollandais","Pour réduire le prix du pain"]'::jsonb, 0, 'Le protectionnisme est le bras armé du mercantilisme.', 7),
    ('0128a4fc-4567-5c8a-8873-a2090a009593'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Qu’est-ce qui ruine finalement les efforts financiers de Colbert ?', 'mcq', '["Le coût des guerres de Louis XIV","La chute du commerce colonial","Une révolte des manufactures","La disparition du canal du Midi"]'::jsonb, 0, 'Les dépenses militaires absorbent l’essentiel des recettes.', 8),
    ('1cb5bb97-58ef-59fb-a367-822f168cc2d5'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Quelles sont les deux grandes composantes de la noblesse d’Ancien Régime ?', 'mcq', '["La noblesse d’épée et la noblesse de robe","La noblesse de cour et la noblesse d’Église","Les ducs et les barons","Les seigneurs et les vassaux"]'::jsonb, 0, 'L’une vient du service militaire, l’autre des offices.', 1),
    ('d368ca84-1779-5e49-a941-a0f0e2f30cd4'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Qu’est-ce que la vénalité des offices ?', 'mcq', '["La possibilité d’acheter une charge publique","L’impôt payé par les nobles","Le droit de rendre la justice","La vente des terres seigneuriales"]'::jsonb, 0, 'Elle remplit les caisses mais rend les titulaires difficiles à révoquer.', 2),
    ('1b630c3f-0b34-54b3-9acf-2407aafafd74'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Qu’est-ce que le droit de remontrance ?', 'mcq', '["Le droit des parlements de critiquer un édit avant de l’enregistrer","Le droit du roi de casser un jugement","Le droit des paysans de pétitionner","Le droit d’appel devant le roi"]'::jsonb, 0, 'Il devient au XVIIIe siècle une arme d’opposition politique.', 3),
    ('0579174e-1329-5003-b355-b273c756f013'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Comment le roi impose-t-il l’enregistrement d’un édit refusé ?', 'mcq', '["Par un lit de justice","Par une lettre de cachet","Par un édit de grâce","Par un concordat"]'::jsonb, 0, 'Le roi vient siéger en personne au parlement.', 4),
    ('a678adb4-618b-5689-afed-09970d9ba18e'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Pourquoi les intendants ne sont-ils pas choisis dans la haute noblesse d’épée ?', 'mcq', '["Pour qu’ils dépendent entièrement du roi et soient révocables","Parce qu’ils sont élus","Parce que la noblesse refuse ces charges","Parce qu’ils doivent être étrangers"]'::jsonb, 0, 'Un agent sans base locale ne peut pas se rendre indépendant.', 5),
    ('a1a505e2-b702-5c85-8d7b-143556bfd987'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'La monarchie a réussi à supprimer les privilèges fiscaux de la noblesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Toutes les tentatives échouent : c’est l’une des causes de 1789.', 6),
    ('2dc48b39-239c-582f-9850-b7b61a55b217'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'À quoi sert la cour de Versailles dans la politique royale ?', 'mcq', '["À tenir la noblesse par les pensions, les charges et l’étiquette","À former les intendants","À loger les parlementaires","À réunir les états généraux"]'::jsonb, 0, 'Une noblesse domestiquée coûte cher mais ne conspire plus.', 7),
    ('262154e0-106c-5fc5-bb12-d844f1f5252b'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Quel événement de 1789 marque l’échec des réformes fiscales de la monarchie ?', 'mcq', '["La convocation des états généraux","La Fronde","La révocation de l’édit de Nantes","La journée des Dupes"]'::jsonb, 0, 'Faute de pouvoir réformer seul, le roi doit convoquer le royaume.', 8),
    ('8b22a9f7-c24c-538d-84bf-1d6a9f41908b'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Que garantit la Grande Charte de 1215 ?', 'mcq', '["Que le roi ne lève pas d’impôt sans l’accord de ses barons","La liberté de la presse","Le suffrage universel","La séparation des pouvoirs"]'::jsonb, 0, 'Le consentement à l’impôt est l’arme du Parlement.', 1),
    ('c10242cb-4578-5618-80b0-a73d9d1b375c'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Quel roi anglais est exécuté en 1649 ?', 'mcq', '["Charles Ier","Jacques II","Charles II","Guillaume III"]'::jsonb, 0, 'Jugé par ses propres sujets, ce qui stupéfie l’Europe.', 2),
    ('9d1adbc9-9695-5fb0-9d6f-e7f88723ccfb'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Qui dirige l’Angleterre après l’exécution de Charles Ier ?', 'mcq', '["Oliver Cromwell","Guillaume d’Orange","Robert Walpole","Jacques II"]'::jsonb, 0, 'République puis protectorat, qui déçoit et prépare la Restauration.', 3),
    ('190f68eb-0bbe-5900-a49a-54f1a48c7f3b'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Que se passe-t-il lors de la Glorieuse Révolution de 1688 ?', 'mcq', '["Le Parlement écarte Jacques II et appelle Guillaume d’Orange","Le roi dissout le Parlement","Cromwell prend le pouvoir","L’Écosse fait sécession"]'::jsonb, 0, 'Une révolution presque sans effusion de sang.', 4),
    ('c71db47b-e3b4-59d5-9eda-bedc86f862bb'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Que fixe le Bill of Rights de 1689 ?', 'mcq', '["Les limites du pouvoir royal face au Parlement","Le droit de vote pour tous","La liberté religieuse totale","L’abolition de la monarchie"]'::jsonb, 0, 'Ni impôt ni armée permanente sans le Parlement.', 5),
    ('2a2744f0-9acf-5743-8a4b-2286236aa96d'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'L’habeas corpus protège contre la détention arbitraire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Voté en 1679, il oblige à présenter tout détenu à un juge.', 6),
    ('bdef9d6c-d19d-5fca-8b17-73b26026063c'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'De quelles chambres le Parlement britannique est-il composé ?', 'mcq', '["Les Communes et les Lords","Le Sénat et l’Assemblée","Les états généraux","Le Conseil privé et la Chambre étoilée"]'::jsonb, 0, 'Deux chambres, aux recrutements très différents.', 7),
    ('3bfbeba2-5a47-5c6e-a853-8949add0bc70'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Le suffrage britannique du XVIIIe siècle est-il universel ?', 'mcq', '["Non, il est très restreint et inégalement réparti","Oui, pour tous les hommes","Oui, pour tous les adultes","Non, il n’existe pas d’élections"]'::jsonb, 0, 'Bourgs pourris et cens élevé : le principe précède l’égalité.', 8),
    ('ee62ee15-7814-53cc-990a-9172e83b260b'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'Quel ouvrage Voltaire publie-t-il en 1734 après son séjour anglais ?', 'mcq', '["Les Lettres philosophiques","Candide","Le Contrat social","De l’esprit des lois"]'::jsonb, 0, 'Un éloge de l’Angleterre qui vaut critique de la France.', 1),
