    ('5e581cdb-9ec2-5bb2-8f60-23a2212435f0'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Où se forme l’opinion publique au XVIIIe siècle ?', 'mcq', '["Dans les cafés, salons, loges et cabinets de lecture","Dans les églises uniquement","À la cour de Versailles","Dans les corporations"]'::jsonb, 0, 'Une sociabilité neuve, hors du contrôle royal.', 5),
    ('6c0c781a-1509-5fe7-98da-19030916a075'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Paris compte environ 600 000 habitants à la veille de la Révolution.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De loin la plus grande ville du royaume.', 6),
    ('6e39fa7f-81f8-5ffc-8bfc-88e32817f2c3'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Que sont les cahiers de doléances ?', 'mcq', '["Les demandes rédigées par les paroisses et les corps en vue des états généraux","Les registres fiscaux du roi","Les comptes des corporations","Les listes de mendiants"]'::jsonb, 0, 'Ceux des villes sont souvent les plus politiques.', 7),
    ('bd07bb8d-7545-53ec-bc2e-18559d4fdb06'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Quel événement parisien du 14 juillet 1789 symbolise l’entrée du peuple urbain en politique ?', 'mcq', '["La prise de la Bastille","La fête de la Fédération","La journée des Tuiles","La marche sur Versailles"]'::jsonb, 0, 'Une forteresse presque vide, mais un symbole du pouvoir arbitraire.', 8),
    ('3065a9f9-4a40-59df-a351-2b22158956dd'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Comment définit-on un risque en géographie ?', 'mcq', '["Le croisement d’un aléa et d’une société vulnérable","Un phénomène naturel violent","Une catastrophe déjà survenue","Une zone inconstructible"]'::jsonb, 0, 'Sans population exposée, il n’y a pas de risque.', 1),
    ('765edcf5-bd56-5dfa-a9b0-076a198468d9'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Qu’est-ce que la vulnérabilité ?', 'mcq', '["La fragilité des populations et des biens face à un aléa","La violence d’un séisme","La fréquence d’un cyclone","La capacité à se reconstruire"]'::jsonb, 0, 'Elle dépend du bâti, des revenus, de l’organisation des secours.', 2),
    ('224c9b8b-f685-51fc-970a-d96626f36b59'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Qu’appelle-t-on la résilience d’un territoire ?', 'mcq', '["Sa capacité à se relever après une catastrophe","Sa richesse par habitant","Sa densité de population","Son taux d’urbanisation"]'::jsonb, 0, 'Elle se prépare avant la crise, pas seulement après.', 3),
    ('1ffa9f4f-b727-591b-bf47-d562710feff4'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Pourquoi un séisme de même magnitude est-il plus meurtrier en Haïti qu’au Japon ?', 'mcq', '["La vulnérabilité y est bien plus forte","L’aléa y est plus intense","Le sol y est plus fragile","La population y est plus dense"]'::jsonb, 0, 'Normes de construction, alerte et secours font la différence.', 4),
    ('23c0eba3-a88d-5716-9dd5-03dba5385b51'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Que s’est-il passé à Fukushima en 2011 ?', 'mcq', '["Un aléa naturel a déclenché un accident technologique","Une explosion industrielle isolée","Une pandémie","Une rupture de barrage"]'::jsonb, 0, 'Séisme, tsunami puis accident nucléaire : un risque hybride.', 5),
    ('deb5911d-f0c1-5b8b-9921-df730775957c'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Les pays du Sud concentrent l’essentiel des victimes des catastrophes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les pays du Nord concentrent en revanche l’essentiel des dégâts matériels.', 6),
    ('b0b84e3c-37e8-5167-aed6-ac4ee39ead26'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Que fait un plan de prévention des risques en France ?', 'mcq', '["Il réglemente ou interdit la construction dans les zones exposées","Il indemnise les sinistrés","Il organise les secours","Il finance la reconstruction"]'::jsonb, 0, 'C’est un outil d’aménagement, annexé au document d’urbanisme.', 7),
    ('36ef8fa9-08b0-522d-8279-d839e2cbf54a'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Quelle différence entre prévision et prévention ?', 'mcq', '["Prévoir, c’est annoncer l’aléa ; prévenir, c’est réduire la vulnérabilité","Ce sont deux synonymes","Prévoir concerne l’industrie, prévenir la nature","Prévenir, c’est indemniser"]'::jsonb, 0, 'L’une est scientifique, l’autre politique et technique.', 8),
    ('879ff266-cc57-5d0e-b1a5-86d0701183ee'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Pourquoi les deltas asiatiques sont-ils très exposés au changement climatique ?', 'mcq', '["Faible altitude, très forte densité et moyens limités","Sols volcaniques instables","Absence de cours d’eau","Climat désertique"]'::jsonb, 0, 'Exposition et vulnérabilité s’y additionnent.', 1),
    ('3f929190-5d15-56eb-9839-8e4fed87cb68'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Combien d’habitants compte environ le Bangladesh ?', 'mcq', '["Environ 170 millions","Environ 40 millions","Environ 600 millions","Environ 90 millions"]'::jsonb, 0, 'Sur un territoire plus petit que la moitié de la France.', 2),
    ('c8fd8247-fc06-5aa4-9492-2005cb69d2e8'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Quel phénomène ruine les rizières côtières du delta ?', 'mcq', '["La salinisation des sols et des nappes","La désertification","Le gel hivernal","L’acidification des pluies"]'::jsonb, 0, 'Elle pousse certains paysans vers l’aquaculture de crevettes.', 3),
    ('31585d35-6b3a-5a19-9351-fd1624951809'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Quelle forêt littorale protège naturellement le delta du Gange ?', 'mcq', '["La mangrove des Sundarbans","La forêt de teck","La taïga","La forêt de mousson du Deccan"]'::jsonb, 0, 'Elle amortit les vagues de tempête et fixe les sédiments.', 4),
    ('ebc1b6a7-d129-552c-9369-d9213b4506af'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Qu’est-ce que l’adaptation, en matière de climat ?', 'mcq', '["Réduire les effets subis, par des digues, des abris ou des cultures adaptées","Réduire les émissions de gaz à effet de serre","Interdire les énergies fossiles","Déplacer les populations"]'::jsonb, 0, 'L’atténuation agit sur la cause, l’adaptation sur les conséquences.', 5),
    ('97b97062-3bc4-5947-9c58-5f6c3234fb69'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'L’accord de Paris sur le climat date de 2015.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il vise à contenir le réchauffement bien en dessous de 2 degrés.', 6),
