    ('eabceb08-5c15-5f40-b1f0-2c4ae8f42495'::uuid, 'ccb4435a-a903-5e03-8b8d-d86d80c204dd'::uuid, 'Quel texte international définit le statut de réfugié ?', 'mcq', '["La convention de Genève de 1951","La charte de l’ONU de 1945","Les accords de Schengen","La convention de Montego Bay"]'::jsonb, 0, 'Elle protège ceux qui fuient des persécutions.', 2),
